const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');
const config = require('./config');
const { MEDALHAS_PADRAO } = require('./regras');
const { hashSenha } = require('./senha');

fs.mkdirSync(config.PASTA_DADOS, { recursive: true });
const db = new DatabaseSync(path.join(config.PASTA_DADOS, 'maxx.db'));

db.exec(`
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS usuarios (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  senha_hash TEXT NOT NULL,
  papel TEXT NOT NULL DEFAULT 'aluno' CHECK (papel IN ('aluno', 'professor', 'admin')),
  curso TEXT,
  bio TEXT NOT NULL DEFAULT '',
  avatar TEXT,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sessoes (
  token_hash TEXT PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  expira_em INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS posts (
  id INTEGER PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  imagem TEXT,
  legenda TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_posts_usuario ON posts(usuario_id);

CREATE TABLE IF NOT EXISTS curtidas (
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, usuario_id)
);

CREATE TABLE IF NOT EXISTS comentarios (
  id INTEGER PRIMARY KEY,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  texto TEXT NOT NULL,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_comentarios_post ON comentarios(post_id);

CREATE TABLE IF NOT EXISTS tipos_medalha (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  emoji TEXT NOT NULL,
  pontos INTEGER NOT NULL,
  descricao TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS medalhas (
  id INTEGER PRIMARY KEY,
  aluno_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  professor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  tipo_id INTEGER NOT NULL REFERENCES tipos_medalha(id),
  mensagem TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_medalhas_aluno ON medalhas(aluno_id);

-- Quando cada aluno desbloqueou cada conquista (para mostrar no feed).
-- anunciar = 0: conquista antiga, registrada sem aparecer no feed.
CREATE TABLE IF NOT EXISTS conquistas_alunos (
  id INTEGER PRIMARY KEY,
  aluno_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  conquista TEXT NOT NULL,
  anunciar INTEGER NOT NULL DEFAULT 1,
  criado_em TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (aluno_id, conquista)
);

CREATE INDEX IF NOT EXISTS idx_posts_data ON posts(criado_em);
CREATE INDEX IF NOT EXISTS idx_medalhas_data ON medalhas(criado_em);

CREATE TABLE IF NOT EXISTS avisos (
  id INTEGER PRIMARY KEY,
  autor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  titulo TEXT NOT NULL,
  texto TEXT NOT NULL,
  fixado INTEGER NOT NULL DEFAULT 0,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
`);

// Dados iniciais: tipos de medalha e conta da faculdade.
if (db.prepare('SELECT COUNT(*) AS n FROM tipos_medalha').get().n === 0) {
  const inserir = db.prepare('INSERT INTO tipos_medalha (nome, emoji, pontos, descricao) VALUES (?, ?, ?, ?)');
  for (const m of MEDALHAS_PADRAO) inserir.run(m.nome, m.emoji, m.pontos, m.descricao);
}

if (!db.prepare("SELECT 1 FROM usuarios WHERE papel = 'admin'").get()) {
  db.prepare("INSERT INTO usuarios (nome, email, senha_hash, papel, bio) VALUES (?, ?, ?, 'admin', ?)").run(
    config.FACULDADE,
    config.ADMIN_EMAIL,
    hashSenha(config.ADMIN_SENHA),
    'Conta oficial da faculdade',
  );
  console.log(`Conta da faculdade criada: ${config.ADMIN_EMAIL} / senha: ${config.ADMIN_SENHA} (troque depois!)`);
}

module.exports = db;
const path = require('node:path');
const fs = require('node:fs');
const crypto = require('node:crypto');
const express = require('express');
const multer = require('multer');

const config = require('./config');
const db = require('./db');
const { hashSenha, confereSenha } = require('./senha');
const pontos = require('./pontos');
const banca = require('./banca');
const feed = require('./feed');
const v = require('./views');

const PASTA_UPLOADS = path.join(config.PASTA_DADOS, 'uploads');
fs.mkdirSync(PASTA_UPLOADS, { recursive: true });

const COOKIE = 'maxx_sessao';
const DURACAO_SESSAO_MS = 30 * 24 * 60 * 60 * 1000;
const POSTS_POR_PAGINA = 20;

// Erro com mensagem que pode ser mostrada ao usuário.
class ErroUsuario extends Error {
  constructor(mensagem, status = 400) {
    super(mensagem);
    this.status = status;
  }
}

// ---------- Upload de imagens ----------
const TIPOS_IMAGEM = { 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp', 'image/gif': '.gif' };
const upload = multer({
  storage: multer.diskStorage({
    destination: PASTA_UPLOADS,
    filename: (req, file, cb) => cb(null, crypto.randomBytes(16).toString('hex') + TIPOS_IMAGEM[file.mimetype]),
  }),
  limits: { fileSize: config.TAMANHO_MAX_IMAGEM_MB * 1024 * 1024, files: 1 },
  fileFilter: (req, file, cb) => {
    if (TIPOS_IMAGEM[file.mimetype]) cb(null, true);
    else cb(new ErroUsuario('Formato de imagem não suportado. Use JPG, PNG, WEBP ou GIF.'));
  },
});

function apagarArquivo(nome) {
  if (nome) fs.rm(path.join(PASTA_UPLOADS, path.basename(nome)), { force: true }, () => {});
}

// ---------- Sessão ----------
const hashToken = (t) => crypto.createHash('sha256').update(t).digest('hex');

function lerCookie(req, nome) {
  for (const parte of (req.headers.cookie || '').split(';')) {
    const [k, ...resto] = parte.trim().split('=');
    if (k === nome) return decodeURIComponent(resto.join('='));
  }
  return null;
}

function iniciarSessao(res, usuarioId) {
  const token = crypto.randomBytes(32).toString('hex');
  db.prepare('INSERT INTO sessoes (token_hash, usuario_id, expira_em) VALUES (?, ?, ?)').run(
    hashToken(token),
    usuarioId,
    Date.now() + DURACAO_SESSAO_MS,
  );
  res.cookie(COOKIE, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: DURACAO_SESSAO_MS,
  });
}

// ---------- Helpers ----------
function enviar(req, res, { titulo, ativo, conteudo, status = 200 }) {
  res.status(status).type('html').send(String(v.layout({ usuario: req.usuario, titulo, ativo, conteudo })));
}

function exigeLogin(req, res, next) {
  if (!req.usuario) return res.redirect('/entrar');
  next();
}

const exigePapel = (...papeis) => (req, res, next) => {
  if (!papeis.includes(req.usuario?.papel)) throw new ErroUsuario('Você não tem permissão para fazer isso.', 403);
  next();
};

// Só aceita caminhos internos para evitar redirecionar para outro site.
const caminhoSeguro = (p, padrao = '/') => (typeof p === 'string' && /^\/(?!\/)/.test(p) && !p.includes('\\') ? p : padrao);

const texto = (valor, max) => String(valor ?? '').trim().slice(0, max);
const idParam = (req) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) throw new ErroUsuario('Página não encontrada.', 404);
  return id;
};

const { SQL_POST } = feed;

// ---------- App ----------
const app = express();
app.disable('x-powered-by');
app.use(express.urlencoded({ extended: false, limit: '100kb' }));
app.use(express.static(path.join(__dirname, '..', 'public')));

app.use((req, res, next) => {
  res.set('X-Content-Type-Options', 'nosniff');
  res.set('X-Frame-Options', 'DENY');
  res.set('Referrer-Policy', 'same-origin');
  const token = lerCookie(req, COOKIE);
  if (token) {
    req.usuario = db
      .prepare('SELECT u.* FROM sessoes s JOIN usuarios u ON u.id = s.usuario_id WHERE s.token_hash = ? AND s.expira_em > ?')
      .get(hashToken(token), Date.now());
    // Contas da banca só valem enquanto o acesso da banca estiver ligado.
    if (req.usuario && !banca.ligada() && banca.ehContaBanca(req.usuario.email)) req.usuario = undefined;
  }
  next();
});
  res.clearCookie(COOKIE);
  res.redirect('/entrar');
});

// Tudo daqui pra baixo exige login.
app.use(exigeLogin);
app.use('/uploads', express.static(PASTA_UPLOADS, { maxAge: '7d' }));

// ----- Feed -----
app.get('/', (req, res) => {
  const pagina = Math.max(1, parseInt(req.query.pagina, 10) || 1);
  const { itens, temMais } = feed.pagina({ usuarioId: req.usuario.id, pagina, porPagina: POSTS_POR_PAGINA });
  const avisoFixado = db.prepare('SELECT * FROM avisos WHERE fixado = 1 ORDER BY id DESC LIMIT 1').get();
  enviar(req, res, {
    ativo: 'inicio',
    conteudo: v.feed({ itens, avisoFixado, pagina, temMais }),
  });
});

// ----- Posts -----
app.get('/novo', (req, res) => enviar(req, res, { titulo: 'Novo post', ativo: 'novo', conteudo: v.novoPost({}) }));
  if (req.file) apagarArquivo(req.usuario.avatar);
  res.redirect(`/u/${req.usuario.id}`);
});

// ----- Ranking -----
app.get('/ranking', (req, res) => {
  const curso = config.CURSOS.includes(req.query.curso) ? req.query.curso : '';
  enviar(req, res, {
    titulo: 'Ranking',
    ativo: 'ranking',
    conteudo: v.ranking({
      lista: pontos.ranking(curso),
      curso,
      usuario: req.usuario,
      tiposMedalha: db.prepare('SELECT * FROM tipos_medalha ORDER BY pontos DESC').all(),
    }),
  });
});

// ----- Mural -----
const listarAvisos = () => db.prepare('SELECT * FROM avisos ORDER BY fixado DESC, id DESC').all();

app.get('/mural', (req, res) =>
