87:.perigo { color: var(--perigo); }
94:.form label.check { display: flex; align-items: center; gap: .5rem; font-weight: 400; }
124:.usuario-link { display: flex; align-items: center; gap: .6rem; color: var(--texto); min-width: 0; }
125:.usuario-link:hover { text-decoration: none; }
126:.usuario-link > span { display: grid; min-width: 0; }
127:.usuario-link small { color: var(--muted); font-size: .78rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
235:.ranking .usuario-link { flex: 1; }

